#!/usr/bin/env python3
"""A small persistent HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY_BYTES = 1024 * 1024


class StoreError(Exception):
    """Raised when durable state cannot be read or written."""


class Store:
    def __init__(self, path: Path) -> None:
        self.path = path
        self._lock = threading.RLock()
        self._entries: dict[str, dict[str, Any]] = {}
        self._load()

    @staticmethod
    def _live(entry: dict[str, Any], now: float) -> bool:
        expires_at = entry["expires_at"]
        return expires_at is None or expires_at > now

    def _load(self) -> None:
        if not self.path.exists():
            return
        try:
            with self.path.open("r", encoding="utf-8") as stream:
                document = json.load(stream, parse_constant=self._reject_constant)
            if not isinstance(document, dict) or document.get("version") != 1:
                raise ValueError("unsupported data-file format")
            raw_entries = document.get("entries")
            if not isinstance(raw_entries, dict):
                raise ValueError("entries must be an object")

            loaded: dict[str, dict[str, Any]] = {}
            now = time.time()
            removed_expired = False
            for key, entry in raw_entries.items():
                if not isinstance(key, str) or not key or "/" in key:
                    raise ValueError("invalid stored key")
                if not isinstance(entry, dict) or set(entry) != {"value", "expires_at"}:
                    raise ValueError("invalid stored entry")
                expires_at = entry["expires_at"]
                if expires_at is not None and (
                    isinstance(expires_at, bool)
                    or not isinstance(expires_at, (int, float))
                    or not math.isfinite(expires_at)
                ):
                    raise ValueError("invalid stored expiration")
                normalized = {"value": entry["value"], "expires_at": expires_at}
                if self._live(normalized, now):
                    loaded[key] = normalized
                else:
                    removed_expired = True
            self._entries = loaded
            if removed_expired:
                self._persist(loaded)
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as exc:
            raise StoreError(f"cannot load data file {self.path}: {exc}") from exc

    @staticmethod
    def _reject_constant(value: str) -> None:
        raise ValueError(f"invalid JSON number {value}")

    def _persist(self, entries: dict[str, dict[str, Any]]) -> None:
        parent = self.path.parent
        try:
            parent.mkdir(parents=True, exist_ok=True)
            descriptor, temporary_name = tempfile.mkstemp(
                prefix=f".{self.path.name}.", suffix=".tmp", dir=parent
            )
            try:
                with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
                    json.dump(
                        {"version": 1, "entries": entries},
                        stream,
                        ensure_ascii=False,
                        allow_nan=False,
                        separators=(",", ":"),
                    )
                    stream.write("\n")
                    stream.flush()
                    os.fsync(stream.fileno())
                os.replace(temporary_name, self.path)
                try:
                    directory_fd = os.open(parent, os.O_RDONLY)
                    try:
                        os.fsync(directory_fd)
                    finally:
                        os.close(directory_fd)
                except OSError:
                    # Directory fsync is not supported on every platform/filesystem.
                    pass
            except BaseException:
                try:
                    os.unlink(temporary_name)
                except OSError:
                    pass
                raise
        except (OSError, TypeError, ValueError) as exc:
            raise StoreError(f"cannot persist data file {self.path}: {exc}") from exc

    def _without_expired(self, now: float) -> tuple[dict[str, dict[str, Any]], bool]:
        live = {key: entry for key, entry in self._entries.items() if self._live(entry, now)}
        return live, len(live) != len(self._entries)

    def put(self, key: str, value: Any, ttl_seconds: float | None) -> bool:
        with self._lock:
            now = time.time()
            live, _ = self._without_expired(now)
            created = key not in live
            expires_at = None if ttl_seconds is None else now + ttl_seconds
            if expires_at is not None and not math.isfinite(expires_at):
                raise ValueError("ttl_seconds is too large")
            replacement = dict(live)
            replacement[key] = {"value": value, "expires_at": expires_at}
            self._persist(replacement)
            self._entries = replacement
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self._lock:
            entry = self._entries.get(key)
            if entry is None:
                return False, None
            if not self._live(entry, time.time()):
                replacement = dict(self._entries)
                del replacement[key]
                self._entries = replacement
                try:
                    self._persist(replacement)
                except StoreError as exc:
                    print(exc, file=sys.stderr, flush=True)
                return False, None
            return True, entry["value"]

    def delete(self, key: str) -> bool:
        with self._lock:
            live, removed_expired = self._without_expired(time.time())
            if key not in live:
                if removed_expired:
                    self._persist(live)
                    self._entries = live
                return False
            replacement = dict(live)
            del replacement[key]
            self._persist(replacement)
            self._entries = replacement
            return True

    def keys(self) -> list[str]:
        with self._lock:
            live, removed_expired = self._without_expired(time.time())
            if removed_expired:
                self._entries = live
                try:
                    self._persist(live)
                except StoreError as exc:
                    print(exc, file=sys.stderr, flush=True)
            return sorted(live)


class KVHTTPServer(ThreadingHTTPServer):
    daemon_threads = False
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: Store) -> None:
        self.store = store
        super().__init__(address, RequestHandler)


class RequestHandler(BaseHTTPRequestHandler):
    server: KVHTTPServer
    protocol_version = "HTTP/1.0"

    def _json_response(self, status: int, payload: Any | None = None) -> None:
        body = b"" if payload is None else json.dumps(
            payload, ensure_ascii=False, allow_nan=False, separators=(",", ":")
        ).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body and self.command != "HEAD":
            self.wfile.write(body)

    def _error(self, status: int, message: str) -> None:
        self._json_response(status, {"error": message})

    def send_error(
        self,
        code: int,
        message: str | None = None,
        explain: str | None = None,
    ) -> None:
        # BaseHTTPRequestHandler uses 501 for an unrecognized method. The API
        # contract treats every unsupported HTTP method as a client error.
        if code == HTTPStatus.NOT_IMPLEMENTED:
            code = HTTPStatus.METHOD_NOT_ALLOWED
        self._error(code, message or HTTPStatus(code).phrase)

    @staticmethod
    def _decode_key(raw_key: str) -> str:
        index = 0
        while index < len(raw_key):
            if raw_key[index] == "%":
                if index + 2 >= len(raw_key) or any(
                    character not in "0123456789abcdefABCDEF"
                    for character in raw_key[index + 1 : index + 3]
                ):
                    raise ValueError("key contains malformed percent encoding")
                index += 3
            else:
                index += 1
        try:
            key = unquote_to_bytes(raw_key).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("key is not valid UTF-8") from exc
        if not key:
            raise ValueError("key must not be empty")
        if "/" in key:
            raise ValueError("key must not contain '/'")
        return key

    def _route(self) -> tuple[str, str | None]:
        try:
            path = urlsplit(self.path).path
        except ValueError:
            return "unknown", None
        if path == "/health":
            return "health", None
        if path == "/v1/keys":
            return "keys", None
        prefix = "/v1/kv/"
        if path.startswith(prefix):
            return "key", path[len(prefix) :]
        return "unknown", None

    def _key_or_error(self, raw_key: str | None) -> str | None:
        try:
            return self._decode_key(raw_key or "")
        except ValueError as exc:
            self._error(HTTPStatus.BAD_REQUEST, str(exc))
            return None

    def _read_json(self) -> Any:
        transfer_encoding = self.headers.get("Transfer-Encoding")
        if transfer_encoding:
            raise RequestBodyError(HTTPStatus.BAD_REQUEST, "transfer encoding is not supported")
        lengths = self.headers.get_all("Content-Length", [])
        if len(lengths) != 1:
            raise RequestBodyError(HTTPStatus.LENGTH_REQUIRED, "exactly one Content-Length is required")
        try:
            length = int(lengths[0], 10)
        except ValueError as exc:
            raise RequestBodyError(HTTPStatus.BAD_REQUEST, "invalid Content-Length") from exc
        if length < 0:
            raise RequestBodyError(HTTPStatus.BAD_REQUEST, "invalid Content-Length")
        if length > MAX_BODY_BYTES:
            raise RequestBodyError(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, "request body exceeds 1 MiB")
        body = self.rfile.read(length)
        if len(body) != length:
            raise RequestBodyError(HTTPStatus.BAD_REQUEST, "incomplete request body")
        try:
            return json.loads(body, parse_constant=Store._reject_constant)
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
            raise RequestBodyError(HTTPStatus.BAD_REQUEST, "malformed JSON") from exc

    def do_GET(self) -> None:
        route, raw_key = self._route()
        if route == "health":
            self._json_response(HTTPStatus.OK, {"status": "ok"})
        elif route == "keys":
            self._json_response(HTTPStatus.OK, {"keys": self.server.store.keys()})
        elif route == "key":
            key = self._key_or_error(raw_key)
            if key is None:
                return
            present, value = self.server.store.get(key)
            if present:
                self._json_response(HTTPStatus.OK, {"key": key, "value": value})
            else:
                self._error(HTTPStatus.NOT_FOUND, "key not found")
        else:
            self._error(HTTPStatus.NOT_FOUND, "route not found")

    def do_PUT(self) -> None:
        route, raw_key = self._route()
        if route != "key":
            self._error(HTTPStatus.NOT_FOUND, "route not found")
            return
        key = self._key_or_error(raw_key)
        if key is None:
            return
        try:
            document = self._read_json()
        except RequestBodyError as exc:
            self._error(exc.status, exc.message)
            return
        if not isinstance(document, dict) or "value" not in document:
            self._error(HTTPStatus.BAD_REQUEST, "body must be an object containing value")
            return
        if not set(document).issubset({"value", "ttl_seconds"}):
            self._error(HTTPStatus.BAD_REQUEST, "body contains unknown fields")
            return
        ttl = document.get("ttl_seconds")
        if ttl is not None and (
            isinstance(ttl, bool)
            or not isinstance(ttl, (int, float))
            or not math.isfinite(ttl)
            or ttl <= 0
        ):
            self._error(HTTPStatus.BAD_REQUEST, "ttl_seconds must be finite and greater than zero")
            return
        try:
            created = self.server.store.put(key, document["value"], ttl)
        except ValueError as exc:
            self._error(HTTPStatus.BAD_REQUEST, str(exc))
        except StoreError as exc:
            print(exc, file=sys.stderr, flush=True)
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "could not persist value")
        else:
            self._json_response(HTTPStatus.CREATED if created else HTTPStatus.OK, {"key": key, "value": document["value"]})

    def do_DELETE(self) -> None:
        route, raw_key = self._route()
        if route != "key":
            self._error(HTTPStatus.NOT_FOUND, "route not found")
            return
        key = self._key_or_error(raw_key)
        if key is None:
            return
        try:
            deleted = self.server.store.delete(key)
        except StoreError as exc:
            print(exc, file=sys.stderr, flush=True)
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "could not persist deletion")
            return
        if deleted:
            self._json_response(HTTPStatus.NO_CONTENT)
        else:
            self._error(HTTPStatus.NOT_FOUND, "key not found")

    def _method_not_allowed(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")

    do_POST = _method_not_allowed
    do_PATCH = _method_not_allowed
    do_HEAD = _method_not_allowed
    do_OPTIONS = _method_not_allowed
    do_CONNECT = _method_not_allowed
    do_TRACE = _method_not_allowed


class RequestBodyError(Exception):
    def __init__(self, status: int, message: str) -> None:
        self.status = status
        self.message = message
        super().__init__(message)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--data", required=True, type=Path)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        store = Store(args.data)
        server = KVHTTPServer((args.host, args.port), store)
    except (OSError, StoreError) as exc:
        print(f"startup failed: {exc}", file=sys.stderr)
        return 1

    stopping = threading.Event()

    def stop(_signum: int, _frame: Any) -> None:
        if not stopping.is_set():
            stopping.set()
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever(poll_interval=0.1)
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
